rollback;
begin;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();owner uuid;manager uuid;v timestamptz;op uuid:=gen_random_uuid();p jsonb;exam uuid:=gen_random_uuid();fee uuid:=gen_random_uuid();bill uuid:=gen_random_uuid();post uuid:=gen_random_uuid();begin
 select id into owner from public.cheongla_profiles where role in('owner','english_director','math_director')and approval_status='approved'and membership_state='active'limit 1;
 select id into manager from public.cheongla_profiles where role='manager'and approval_status='approved'and membership_state='active'limit 1;
 if owner is null or manager is null then raise exception 'fixture staff missing';end if;
 insert into auth.users(id,email,raw_user_meta_data)values(a,'merge-a-'||a||'@example.invalid','{"full_name":"계정통합 검증 A","contact_phone":"01000000991"}'),(b,'merge-b-'||b||'@example.invalid','{"full_name":"계정통합 검증 B","contact_phone":"01000000992"}');
 update public.cheongla_profiles set role='student',approval_status='approved'where id in(a,b);
 if public.cheongla_signup_access_hook('{}')<>'{}'::jsonb then raise exception 'signup still SMS gated';end if;
 if has_function_privilege('authenticated','public.cheongla_manual_recovery_job(uuid,uuid,uuid,text,text,timestamptz)','execute')or has_function_privilege('anon','public.cheongla_manual_account(uuid)','execute')then raise exception 'permission exposure';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.cheongla_preview_account_merge(a,b);raise exception 'FAIL student merge';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 begin perform public.cheongla_preview_account_merge(a,b);raise exception 'FAIL manager merge';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.role','service_role',true);
 select membership_updated_at into v from public.cheongla_profiles where id=a;
 begin perform public.cheongla_manual_recovery_job(a,b,op,'issue','fake',v);raise exception 'FAIL nonadmin recovery';exception when insufficient_privilege then null;end;
 perform public.cheongla_manual_recovery_job(owner,a,op,'issue','가입 번호 통화 검증',v);
 perform set_config('request.jwt.claim.sub',a::text,true);
 if not public.cheongla_account_recovery_state()or cheongla_private.can_use_member_services()then raise exception 'FAIL recovery gate';end if;
 begin update public.cheongla_profiles set approval_status='approved'where id=a;raise exception 'FAIL bypass gate';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
 perform public.cheongla_manual_recovery_job(owner,a,op,'issued');
 op:=gen_random_uuid();perform public.cheongla_manual_recovery_job(a,a,op,'finish_begin');perform public.cheongla_manual_recovery_job(a,a,op,'finish');
 if public.cheongla_account_recovery_state()or not cheongla_private.can_use_member_services()then raise exception 'FAIL recovery complete';end if;
 perform set_config('request.jwt.claim.role','authenticated',true);
 perform set_config('request.jwt.claim.sub',owner::text,true);
 insert into public.cheongla_exams(id,title,exam_on,deadline,body,status)values(exam,'통합 검증',date '2099-11-01','2099-10-30','검증','open');
 insert into public.cheongla_exam_applications(exam_id,student_id,student_name,status)values(exam,a,'계정통합 검증 A','registered');
 insert into public.cheongla_exam_fee_notices(id,exam_id,student_id,student_name,exam_title,exam_on,amount,due_on,status)values(fee,exam,a,'검증','통합 검증','2099-11-01',23000,'2099-10-30','published');
 insert into cheongla_private.fee_payments(notice_kind,notice_id,paid_at,paid_amount,updated_by)values('exam',fee,clock_timestamp(),23000,owner);
 insert into public.cheongla_meal_forms(month,deadline)values('2099-11-01','2099-10-25')on conflict do nothing;
 insert into public.cheongla_meal_submissions(month,student_id,student_name,lunch,dinner)values('2099-11-01',a,'검증',array[date '2099-11-01'],'{}');
 insert into public.cheongla_meal_bills(id,month,student_id,student_name,lunch_count,dinner_count,unit_price,adjustment,amount,due_on,source_updated_at)select bill,month,student_id,student_name,1,0,7500,0,7500,'2099-11-01',updated_at from public.cheongla_meal_submissions where student_id=a;
 insert into public.cheongla_board_posts(id,author_id,author_name,title,body,visibility)values(post,a,'검증','통합검증','통합검증','private');
 insert into public.cheongla_mbti_preferences(user_id,mbti)values(a,'ISTP'),(b,'ENFP');
 insert into public.cheongla_parent_students(parent_id,student_id,created_by)select id,a,owner from public.cheongla_profiles where role='parent'and approval_status='approved'limit 1;
 p:=public.cheongla_preview_account_merge(a,b);
 if(p->>'can_merge')<>'true'then raise exception 'FAIL eligible preview %',p->'conflicts';end if;
 -- A concurrent write invalidates the preview, with no partial moves.
 update public.cheongla_board_posts set body='변경된 내용'where id=post;
 begin perform public.cheongla_merge_accounts(a,b,p->>'fingerprint','검증','계정통합');raise exception 'FAIL stale accepted';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
 insert into public.cheongla_meal_submissions(month,student_id,student_name,lunch,dinner)values('2099-11-01',b,'검증','{}','{}');
 p:=public.cheongla_preview_account_merge(a,b);if(p->>'can_merge')<>'false'then raise exception 'FAIL conflict undetected';end if;
 begin perform public.cheongla_merge_accounts(a,b,p->>'fingerprint','검증','계정통합');raise exception 'FAIL conflict merged';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
 delete from public.cheongla_meal_submissions where student_id=b;
 p:=public.cheongla_preview_account_merge(a,b);perform public.cheongla_merge_accounts(a,b,p->>'fingerprint','동일인 계정 검증','계정통합');
 if not exists(select 1 from public.cheongla_exam_applications where student_id=b and exam_id=exam)or not exists(select 1 from public.cheongla_exam_fee_notices where id=fee and student_id=b and amount=23000)or not exists(select 1 from cheongla_private.fee_payments where notice_id=fee and paid_amount=23000)then raise exception 'FAIL exam/payment preservation';end if;
 if not exists(select 1 from public.cheongla_meal_bills where id=bill and student_id=b and amount=7500)or not exists(select 1 from public.cheongla_meal_submissions where student_id=b and lunch=array[date '2099-11-01'])then raise exception 'FAIL meal preservation';end if;
 if not exists(select 1 from public.cheongla_board_posts where id=post and author_id=b and body='변경된 내용')or(select mbti from public.cheongla_mbti_preferences where user_id=b)<>'ENFP'then raise exception 'FAIL board/MBTI preservation';end if;
 if(select membership_state from public.cheongla_profiles where id=a)<>'withdrawn'or not(public.cheongla_account_access_hook(jsonb_build_object('user_id',a,'claims','{}'::jsonb))?'error')then raise exception 'FAIL merged source login';end if;
 if not exists(select 1 from cheongla_private.account_merges where source_id=a and target_id=b and snapshot?'contacts')then raise exception 'FAIL audit';end if;
end;$$;
rollback;
select 'PASS: manual recovery gate, signup manual approval, principal-only merge, stale/conflict rejection, exam/meal composite keys, payment/board/MBTI preservation, source login blocked, private audit; synthetic tests rolled back.'as result;
